cat >> tests/tasks.test.ts <<'EOF'

/** Opens the server's own SQLite file so a test can store rows the API cannot produce on demand. */
function openStore(dbPath: string): DatabaseSync {
  return new DatabaseSync(dbPath);
}

describe("SL-008 list open tasks newest first, with an empty state", () => {
  describe("AC-1: tasks added as A, B, C", () => {
    let server: Running;

    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: the list reads C, B, A", async () => {
      for (const title of ["A", "B", "C"]) {
        assert.equal((await createTask(server, title)).status, 201);
      }
      const titles = (await listTasks(server)).map((task) => task.title);
      assert.deepEqual(titles, ["C", "B", "A"]);
    });
  });

  describe("AC-2: tasks created at the same instant", () => {
    const dbPath = newDbPath();
    let server: Running;

    before(async () => {
      server = await startServer(dbPath);
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-2: the one saved last is listed first, every time", async () => {
      const instant = "2026-01-01T00:00:00.000Z";
      const store = openStore(dbPath);
      try {
        for (const title of ["first", "second", "third"]) {
          store
            .prepare("INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?)")
            .run(title, instant, instant);
        }
      } finally {
        store.close();
      }

      for (let attempt = 0; attempt < 5; attempt++) {
        const titles = (await listTasks(server)).map((task) => task.title);
        assert.deepEqual(titles, ["third", "second", "first"]);
      }
    });

    it("AC-2: creation time decides before the id does", async () => {
      const store = openStore(dbPath);
      try {
        store
          .prepare("INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?)")
          .run("older, saved later", "2025-01-01T00:00:00.000Z", "2025-01-01T00:00:00.000Z");
      } finally {
        store.close();
      }

      const titles = (await listTasks(server)).map((task) => task.title);
      assert.deepEqual(titles, ["third", "second", "first", "older, saved later"]);
    });

    it("AC-2: tasks posted back to back come out in reverse order of posting", async () => {
      const fresh = await startServer();
      try {
        const expected: string[] = [];
        for (let i = 0; i < 30; i++) {
          expected.unshift(`task ${i}`);
          await createTask(fresh, `task ${i}`);
        }
        const titles = (await listTasks(fresh)).map((task) => task.title);
        assert.deepEqual(titles, expected);
      } finally {
        await fresh.stop();
      }
    });
  });

  describe("AC-3: an empty list", () => {
    let server: Running;
    let html: string;
    let script: string;

    before(async () => {
      server = await startServer();
      html = await (await fetch(`${server.baseUrl}/`)).text();
      script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-3: the API answers 200 with no tasks and no error", async () => {
      const response = await fetch(`${server.baseUrl}/api/tasks`);
      assert.equal(response.status, 200);
      assert.deepEqual(await response.json(), { tasks: [] });
    });

    it("AC-3: the page has an empty-state element that starts hidden", () => {
      assert.match(html, /<[a-z]+(?=[^>]*id=["']empty-state["'])(?=[^>]*\shidden)[^>]*>/);
    });

    it("AC-3: the page script shows the empty state only when there are no tasks", () => {
      assert.match(script, /empty-state/);
      assert.match(script, /emptyState\.hidden\s*=\s*tasks\.length\s*>\s*0/);
    });
  });

  describe("AC-4: about 1000 stored tasks", () => {
    const dbPath = newDbPath();
    let server: Running;

    before(async () => {
      server = await startServer(dbPath);
      const store = openStore(dbPath);
      try {
        const insert = store.prepare(
          "INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?)",
        );
        store.exec("BEGIN");
        for (let i = 0; i < 1000; i++) {
          const at = new Date(Date.UTC(2026, 0, 1) + i * 1000).toISOString();
          insert.run(`Task ${i}: ${"x".repeat(100)}`, at, at);
        }
        store.exec("COMMIT");
      } finally {
        store.close();
      }
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-4: 20 sequential requests have p95 under 100 ms and a body under 400000 bytes", async () => {
      const durations: number[] = [];
      let bytes = 0;
      for (let i = 0; i < 20; i++) {
        const started = performance.now();
        const response = await fetch(`${server.baseUrl}/api/tasks`);
        const body = await response.arrayBuffer();
        durations.push(performance.now() - started);
        assert.equal(response.status, 200);
        bytes = body.byteLength;
      }
      durations.sort((a, b) => a - b);
      const p95 = durations[Math.ceil(durations.length * 0.95) - 1];
      assert.ok(p95 < 100, `p95 was ${p95.toFixed(1)} ms`);
      assert.ok(bytes < 400000, `body was ${bytes} bytes`);
      assert.equal((await listTasks(server)).length, 1000);
    });
  });
});
EOF
